// Regenerates buybot/manifest.json from on-disk contents of each tier
// folder. Also writes a summary table to GITHUB_STEP_SUMMARY when
// running in CI so the Actions UI shows what landed at a glance.
//
// Invoked by .github/workflows/regenerate-manifest.yml. Run locally
// with `node .github/scripts/regenerate-manifest.js` from repo root
// to preview the output before pushing.

const fs = require("fs");
const path = require("path");
const TIERS = require("./manifest-tiers");

const ACCEPT_EXT = /\.(png|jpe?g|gif)$/i;

function listTier(folder) {
  const dir = path.join("buybot", folder);
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir)
    .filter((f) => ACCEPT_EXT.test(f))
    .sort()
    .map((f) => `${folder}/${f}`);
}

const lists = Object.fromEntries(TIERS.map((t) => [t.key, listTier(t.folder)]));

const manifest = {
  $schema: "https://json-schema.org/draft/2020-12/schema",
  description:
    "Asset manifest for the NikePig buy bot. Auto-regenerated by " +
    ".github/workflows/regenerate-manifest.yml on changes to " +
    TIERS.map((t) => `${t.folder}/`).join(", ") + ".",
  version: 4,
  ...lists,
};

const out = JSON.stringify(manifest, null, 2) + "\n";
// Round-trip through JSON.parse so a future bug in this script can't
// commit garbage that the bot then 500s on at startup.
JSON.parse(out);
fs.writeFileSync(path.join("buybot", "manifest.json"), out);

const summary = TIERS.map((t) => `${lists[t.key].length} ${t.folder}`).join(" + ");
console.log(`Regenerated: ${summary}`);

if (process.env.GITHUB_STEP_SUMMARY) {
  const md = [
    "## Manifest regenerated",
    "",
    "| Tier | Files |",
    "|------|-------|",
    ...TIERS.map((t) => `| ${t.folder} | ${lists[t.key].length} |`),
    "",
  ].join("\n");
  fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, md);
}
